let directoryStats={},boardPeriod=location.pathname==='/daily'?'today':'all',boardPage=1,searchOpen=false,activityExpanded=false;
const symbols={All:'⊞',Leaderboards:'♜',SEO:'◎',Marketing:'⚑',Productivity:'☷',Agents:'♙',Crypto:'₿',Other:'◇',Developer:'⌘',Health:'♡',Business:'▣',Games:'♧',Ecommerce:'▤',Travel:'✈',Directories:'▦',Agencies:'♜','AI Media':'▧',Social:'◉',Education:'▱',People:'♙',Design:'✧',Hiring:'⊕',Domains:'◎',Security:'♧',Sales:'↗',News:'▤','Real Estate':'⌂',Writing:'✎',Audio:'♫',Analytics:'▥'};
const normalCategory=c=>({Development:'Developer',Founders:'Business',Consulting:'Agencies'}[c]||c);
const iconPaths={All:'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="M3 10h18M10 3v18"/>',Leaderboards:'<path d="M8 3h8v7a4 4 0 0 1-8 0ZM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 14v6m-4 1h8"/>',SEO:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',Marketing:'<path d="m4 9 15-5v16L4 15Zm4 7 1 5h4l-2-4M3 9v6"/>',Productivity:'<path d="m3 6 2 2 3-4m3 2h10M3 13l2 2 3-4m3 2h10M3 20l2 2 3-4m3 2h10"/>',Agents:'<rect x="5" y="7" width="14" height="13" rx="3"/><path d="M12 3v4M2 11v5m20-5v5M9 12v2m6-2v2m-6 3h6"/>',Other:'<path d="M9 3h6v4h4v6h-4v6H9v-4H3V9h6Z"/>',Developer:'<path d="m7 6-5 6 5 6m10-12 5 6-5 6M14 3l-4 18"/>'};
const icon=c=>iconPaths[c]?`<svg class="category-icon line-icon" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[c]}</svg>`:`<span class="category-icon" aria-hidden="true">${symbols[c]||'◇'}</span>`;
const relative=t=>{const n=Math.max(0,now()-t);return n<60000?'just now':n<3600000?Math.floor(n/60000)+' min ago':n<86400000?Math.floor(n/3600000)+' hours ago':Math.floor(n/86400000)+' days ago'};
const dailyPeople=()=>livePeople().filter(p=>(p.activityAt||p.created)>=Date.parse(new Date(now()).toISOString().slice(0,10)+'T00:00:00Z'));
const directoryList=()=> (boardPeriod==='today'?dailyPeople():livePeople()).filter(p=>(filter==='All people'||normalCategory(p.category)===filter)&&(!search||(p.name+' '+p.headline+' '+p.location).toLowerCase().includes(search))).map((p,i)=>({...p,rank:i+1}));
function categoryRail(){return `<div class="category-bar"><div class="category-scroll"><a class="category-tab ${filter==='All people'?'selected':''}" href="/">${icon('All')}All</a>${cats.map(c=>`<a class="category-tab ${filter===c?'selected':''}" href="/?category=${encodeURIComponent(c)}">${icon(c)}${c}</a>`).join('')}</div><a class="category-explore" href="/categories">${icon('All')}Explore</a></div>`}
function headerSetup(){const h=document.querySelector('header');if(!h)return;const brand=h.querySelector('.brand').outerHTML;h.innerHTML=`<div class="directory-brand-row">${brand}<a class="site-counts" href="/stats"><span id="live-count">${livePeople().length} fuelled</span><span id="registered-count">${directoryStats.profiles||0} profiles</span><span>stats →</span></a></div><nav aria-label="Main navigation"><a href="/daily">Daily</a><a href="/categories">Categories</a><a href="/about">About</a><a href="/rules">Rules</a><a class="header-search" href="/?search=1" aria-label="Search profiles"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/></svg></a><button id="theme-toggle" aria-label="Toggle dark mode" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 15.5A9 9 0 0 1 8.5 4 9 9 0 1 0 20 15.5Z"/></svg></button><a class="header-account" href="/account" aria-label="My dashboard"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.5"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/></svg></a></nav>`;const saved=(()=>{try{return localStorage.getItem('linkdid-theme')}catch{return null}})();if(saved==='dark')document.documentElement.dataset.theme='dark';const b=$('#theme-toggle');b.setAttribute('aria-pressed',String(document.documentElement.dataset.theme==='dark'));b.onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';b.setAttribute('aria-pressed',String(dark));try{localStorage.setItem('linkdid-theme',dark?'dark':'light')}catch{}}}
footer=()=>`<footer class="directory-footer"><p>Linkdid.ai · A spotlight for LinkedIn professionals.</p><div><a href="/rules">Rules</a><span>·</span><a href="/faq">FAQ</a><span>·</span><a href="/support">Support</a><span>·</span><a href="/billing">Payments</a><span>·</span><a href="/stats">Live stats</a><span>·</span><a href="/account">My dashboard</a></div><small>Independent platform. Not affiliated with LinkedIn.</small></footer>`;
const previousShell=shell;
shell=content=>{previousShell(content);headerSetup()};
function directoryStatsMarkup(){return `<section class="directory-stats" id="statistics"><p>A little look at Linkdid.ai, in numbers</p><div><a href="/categories"><strong>${directoryStats.profiles||0}</strong><span>profiles added</span></a><a href="/"><strong>${livePeople().length}</strong><span>fuelled profiles</span></a><div><strong>${directoryStats.clicks||0}</strong><span>LinkedIn clicks</span></div></div></section>`}
function profileRow(p){const c=normalCategory(p.category);return `<article class="profile ${p.rank===1?'first':''}"><span class="rank">#${p.rank}</span><a href="/profile/${p.id}" aria-label="View ${esc(p.name)}">${avatar(p)}</a><div class="profile-copy"><div class="person-name"><a href="/profile/${p.id}">${esc(p.name)}</a></div><p class="headline">${esc(p.headline)}</p><div class="meta"><a class="tag" href="/?category=${encodeURIComponent(c)}">${icon(c)}${esc(c)}</a><span>·</span><span>${relative(p.created)}</span><span>·</span><a href="/go/${p.id}" target="_blank" rel="noopener">LinkedIn ↗</a><span>·</span><span>${Number(p.clicks||0).toLocaleString()} clicks</span><span>·</span><a href="/profile/${p.id}">see details</a></div></div><div class="row-fuel"><strong data-gas-free="${p.free}" data-gas-paid="${p.paid}" data-gas-at="${now()}">${litres(p.total)} L</strong><a href="/claim?target=${Math.ceil(p.total+1)}">Claim this rank ↗</a></div></article>`}
function todayMarkup(){const a=dailyPeople().filter(p=>filter==='All people'||normalCategory(p.category)===filter).slice(0,3);return `<section class="today-section"><div class="section-heading"><h2><span class="blue-dot"></span>Today’s top ranking</h2><a href="/daily${filter==='All people'?'':'?category='+encodeURIComponent(filter)}">See all ›</a></div><div class="today-cards">${a.length?a.map((p,i)=>`<a class="today-card" href="/profile/${p.id}"><b>#${i+1}</b>${avatar(p)}<div><strong>${esc(p.name)}</strong><p>${esc(p.headline)}</p></div><em>${litres(p.total)} L</em></a>`).join(''):'<div class="today-empty">No fuelled profiles active today. <a href="/claim">Take the first spot →</a></div>'}</div></section>`}
function activityMarkup(){const a=[...livePeople()].sort((a,b)=>(b.activityAt||b.created)-(a.activityAt||a.created)).slice(0,activityExpanded?20:5);return `<section class="activity-section"><h2>Latest activity</h2>${a.length?`<ul>${a.map(p=>`<li><a href="/profile/${p.id}">${esc(p.name)}</a><span>at #${p.rank} · ${litres(p.total)} L</span><time>${relative(p.activityAt||p.created)}</time></li>`).join('')}</ul>`:'<p>Your next refill could start the activity feed.</p>'}${livePeople().length>5?'<button class="activity-more" id="activity-more">'+(activityExpanded?'Show less':'Show more')+'</button>':''}</section>`}
rows=()=>{if(!$('#profiles'))return;const list=directoryList();boardPage=Math.min(boardPage,Math.max(1,Math.ceil(list.length/50)));const slice=list.slice((boardPage-1)*50,boardPage*50);let out='';if(!slice.length)out=`<section class="directory-empty"><h2>${search?'No matching profiles.':filter!=='All people'?'Be the first in '+esc(filter)+'.':'Your profile belongs here.'}</h2><p>${search?'Try a different name, skill or location.':'Fill your tank to take your place on the leaderboard.'}</p><a class="button dark" href="/claim">Claim rank</a></section>`;else slice.forEach((p,i)=>{out+=profileRow(p);if(i===2&&boardPeriod==='all')out+=todayMarkup();if(i===9)out+=activityMarkup()});if(slice.length<3||boardPeriod==='today')out+=todayMarkup();if(slice.length<=9)out+=activityMarkup();$('#profiles').innerHTML=out;
 const pages=Math.ceil(list.length/50);$('#directory-pagination').innerHTML=pages>1?Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${i+1===boardPage?'selected':''}" aria-label="Page ${i+1}">${i+1}</button>`).join('')+`<span>${(boardPage-1)*50+1}–${Math.min(boardPage*50,list.length)} of ${list.length}</span>`:'';document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{boardPage=Number(b.dataset.page);rows();$('#profiles').scrollIntoView({behavior:'smooth'})});if($('#activity-more'))$('#activity-more').onclick=()=>{activityExpanded=!activityExpanded;rows()};if($('#live-count'))$('#live-count').textContent=livePeople().length+' fuelled';if($('#registered-count'))$('#registered-count').textContent=(directoryStats.profiles||0)+' profiles';images();};
home=()=>{document.title='Linkdid.ai — Claim your rank';document.body.classList.add('reference-home','outbid-layout');const params=new URLSearchParams(location.search);filter=cats.includes(params.get('category'))?params.get('category'):'All people';searchOpen=params.get('search')==='1';const target=Math.min(5000,Math.max(1,Math.ceil((directoryList()[0]?.total||0)+1)));
 shell(`${categoryRail()}<section class="claim-surface"><div class="period-switch" aria-label="Ranking period"><a href="/${filter==='All people'?'':'?category='+encodeURIComponent(filter)}" class="${boardPeriod==='all'?'selected':''}" ${boardPeriod==='all'?'aria-current="page"':''}>${icon('Leaderboards')}All-time</a><a href="/daily${filter==='All people'?'':'?category='+encodeURIComponent(filter)}" class="${boardPeriod==='today'?'selected':''}" ${boardPeriod==='today'?'aria-current="page"':''}><span class="blue-dot"></span>Today</a></div><h1>Claim #1 for <span class="amount-control"><button type="button" id="gas-minus" aria-label="Decrease target gas">−</button><label><input id="entry-amount" type="number" min="1" max="5000" step="1" value="${target}" aria-label="Target gas in litres" form="quick-claim" name="target"><span>L</span></label><button type="button" id="gas-plus" aria-label="Increase target gas">+</button></span></h1><form id="quick-claim" action="/claim"><label class="url-entry"><span class="in">in</span><input type="url" name="profileLink" aria-label="Your LinkedIn profile URL" placeholder="Your LinkedIn profile URL" value="${esc(account?.profile?.url||'')}"></label><select id="entry-category" name="specialty" aria-label="Choose a category"><option value="">Choose category</option>${cats.map(c=>`<option ${normalCategory(account?.profile?.category)===c?'selected':''}>${c}</option>`).join('')}</select><button class="button dark" type="submit">Claim rank</button></form><p class="claim-note">Free gas or $1/L · ${boardPeriod==='today'?'Today shows profiles active since 00:00 UTC.':'Highest remaining gas ranks first.'}</p><p id="entry-error" role="alert"></p></section><section class="directory-search" ${searchOpen?'':'hidden'}><label class="search"><span>⌕</span><input id="search" type="search" placeholder="Search people, skills or location" aria-label="Search profiles" value="${esc(search)}"></label><button class="text-btn" id="refresh">Refresh ↻</button></section><section class="leaderboard"><div id="profiles"></div><div id="directory-pagination"></div></section>${directoryStatsMarkup()}`);
 rows();const amount=$('#entry-amount');const adjust=delta=>{amount.value=Math.max(1,Math.min(5000,(Number(amount.value)||1)+delta));updateTarget()};function updateTarget(){const rank=directoryList().filter(p=>p.total>=Number(amount.value)).length+1;$('.claim-surface h1').firstChild.textContent='Claim #'+rank+' for ';amount.style.width=Math.max(1.1,String(amount.value).length*.68)+'em'}$('#gas-minus').onclick=()=>adjust(-1);$('#gas-plus').onclick=()=>adjust(1);amount.oninput=updateTarget;updateTarget();$('#quick-claim').onsubmit=e=>{const v=e.target.elements.profileLink.value.trim();if(v){try{const u=new URL(v);if(u.protocol!=='https:'||!['linkedin.com','www.linkedin.com'].includes(u.hostname)||!/^\/in\/[^/]+\/?$/.test(u.pathname)||u.username||u.password)throw Error()}catch{e.preventDefault();$('#entry-error').textContent='Use a LinkedIn profile URL, such as https://www.linkedin.com/in/your-name.'}}};$('#search').oninput=e=>{search=e.target.value.toLowerCase();boardPage=1;rows()};$('#refresh').onclick=()=>refresh(true);if(searchOpen)$('#search').focus();};
function directoryPage(){document.body.classList.add('reference-home','outbid-layout');const path=location.pathname;let content='';if(path==='/categories'){document.title='Categories — Linkdid.ai';content=`<section class="category-page"><h1>Explore categories</h1><p>Find your people. Choose a category to explore the leaderboard.</p><div class="category-grid">${cats.map(c=>`<a href="/?category=${encodeURIComponent(c)}">${icon(c)}<div><h2>${c}</h2><span>${livePeople().filter(p=>normalCategory(p.category)===c).length} fuelled profiles</span></div><b>↗</b></a>`).join('')}</div></section>`}else if(path==='/stats'){document.title='Live stats — Linkdid.ai';content=directoryStatsMarkup()}else{document.title=(path==='/faq'?'FAQ':'Rules')+' — Linkdid.ai';content=`<section class="directory-info"><h1>${path==='/faq'?'Frequently asked questions':'Simple rules. A fair spotlight.'}</h1>${[['How is my rank decided?','Your remaining free and paid gas are added together. The highest total ranks first. Equal balances use profile creation time, then profile ID.'],['How do I fill gas for free?','Press and hold the pump for 60 seconds to earn 1 litre. Release to pause. Each litre stops the pump automatically; release and press again for the next. Free gas uses 1 litre per hour.'],['How does purchased gas work?','Paid gas costs $1 per litre and uses 1 litre every 24 hours. Crypto checkout becomes available after the merchant connection is activated. Gas is credited only after payment verification.'],['What does Today show?','Today includes fuelled profiles with activity since 00:00 UTC, ranked by their current total gas. All-time includes all currently fuelled profiles. Neither view preserves a historical gas balance.'],['Does gas guarantee a rank?','No. Balances keep decreasing, and other people can fill their tanks. Both tanks drain while you are offline. Empty profiles leave the leaderboard; your saved profile remains.'],['Does this change LinkedIn rankings?','Placement is on Linkdid.ai only. Profiles are self-submitted. Linkdid.ai is independent of LinkedIn and does not guarantee followers, clients or LinkedIn reach.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}<a class="button dark" href="/claim">Claim your spot</a></section>`}shell(categoryRail()+content)}
// Keep the shared dashboard compatible with older category names.
const directoryDashboard=dashboard;dashboard=()=>{directoryDashboard();const form=$('#profile-form');if(form&&account?.profile)form.elements.category.value=normalCategory(account.profile.category)};
const directoryClaim=claimPage;claimPage=async()=>{await directoryClaim();const n=Number(new URLSearchParams(location.search).get('target')),form=$('#gas-purchase');if(form&&Number.isInteger(n)&&n>=1&&n<=5000){form.elements.litres.value=n;form.elements.litres.oninput()}};
